import {
    httpOperations,
    type HttpOperationDefinition,
} from '../../../../contracts/v1/http-operations.ts'

function option(value: string | undefined) {
    return value === undefined ? 'None' : 'Some(' + JSON.stringify(value) + ')'
}

export function buildRustOperations() {
    const entries: [string, HttpOperationDefinition][] = Object.entries(httpOperations)
    const operations = entries.map(
        ([id, operation]) => ({
            id,
            variant: id.charAt(0).toUpperCase() + id.slice(1),
            operation,
        }),
    )

    return [
        '// Generated by bun run contracts:generate.',
        '',
        'use super::{HttpDescriptor, HttpMethod, HttpSocket};',
        '',
        '#[derive(Clone, Copy, Debug, Eq, PartialEq)]',
        'pub enum HttpOperation {',
        ...operations.map(({ variant }) => '    ' + variant + ','),
        '}',
        '',
        'impl HttpOperation {',
        '    pub fn from_id(id: &str) -> Option<Self> {',
        '        match id {',
        ...operations.map(
            ({ id, variant }) => '            "' + id + '" => Some(Self::' + variant + '),',
        ),
        '            _ => None,',
        '        }',
        '    }',
        '',
        "    pub fn id(self) -> &'static str {",
        '        match self {',
        ...operations.map(
            ({ id, variant }) => '            Self::' + variant + ' => "' + id + '",',
        ),
        '        }',
        '    }',
        '',
        '    pub fn descriptor(self) -> HttpDescriptor {',
        '        match self {',
        ...operations.flatMap(({ variant, operation }) => [
            '            Self::' + variant + ' => HttpDescriptor {',
            '                method: HttpMethod::' + (operation.method === 'GET' ? 'Get' : 'Post') + ',',
            '                socket: HttpSocket::' + (operation.socket === 'app.sock' ? 'App' : 'Core') + ',',
            '                path: ' + JSON.stringify(operation.path) + ',',
            '                path_parameter: ' + option(operation.pathParameter) + ',',
            '                idempotency_key: ' + Boolean(operation.idempotencyKey) + ',',
            '                resume_cursor: ' + Boolean(operation.resumeCursor) + ',',
            '                request: ' + option(operation.request) + ',',
            '                success_status: ' + operation.status + ',',
            '                response: ' + option(operation.response) + ',',
            '                event: ' + option(operation.event) + ',',
            '            },',
        ]),
        '        }',
        '    }',
        '}',
        '',
    ].join('\n')
}
